#!/usr/bin/env node
/**
 * The committed world content is what the builder produces, covers every room,
 * and asks the viewer only for things it can draw.
 *
 * `src/data/world/` is a derived artefact the way `src/data/map/` is: 86 files,
 * one per zone plus an index, generated by `tools/build-world-content.mjs` and
 * committed so the app can import a zone without running a build step. A
 * derived file that is committed is a file somebody will eventually hand-edit,
 * and the edit will look exactly like a rule change that nobody made. So:
 *
 *   1. re-running the builder reproduces every byte of it;
 *   2. every room in `src/data/map/` has a content entry, counted N of N;
 *   3. every primitive kind the content asks for is one a factory is
 *      registered for — the set read out of `godot/scripts/shared_asset_content.gd`
 *      rather than typed here, so a kind renamed in GDScript takes this red;
 *   4. the unknown share is under the ceiling the builder publishes;
 *   5. the vocabularies are total: every ground kind maps to a block kind,
 *      every block kind is one of the four, every rule named in a record is one
 *      of the declared rules.
 *
 * Every count is asserted against a floor as well as a property. "No room is
 * missing its content entry" is true, and empty, of a run that read no rooms —
 * the same defect `tools/build-world-content.mjs` guards its own input with.
 *
 *   node --experimental-strip-types tools/world-content-test.mjs
 *
 * `--experimental-strip-types` because the builder it shells out to imports
 * `src/lib/mapLandmarks.ts`.
 */
import { execFileSync } from 'node:child_process'
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import {
  BLOCK_KINDS,
  COHORT_MAJORITY_DENOMINATOR,
  COHORT_MAJORITY_NUMERATOR,
  GROUND_KINDS,
  GROUND_RULES,
  THRESHOLD_DIRECTIONS,
  blockKindFor,
  placeCohorts,
  primitivesFor,
  ruleStrength,
  unifyPlaceCohort,
} from '../src/lib/world-content-rules.mjs'
import { NO_CONTENT_PACK_REASON, findContentPack } from './godot-content-pack.mjs'

const MAP_DIR = 'src/data/map'
const WORLD_DIR = 'src/data/world'

/**
 * Floors, not comments.
 *
 * `src/lib/mapData.ts` states 17,750 rooms in 85 zones and
 * `tools/map-data-test.mjs` holds it to that; these sit well below, so they
 * catch an empty or half-copied data directory without needing to be touched
 * when the map is rebuilt. Without them, "every room has an entry" and "no kind
 * is undrawable" are both true of zero rooms, which is the most reassuring
 * output this file can produce and means nothing.
 */
const MIN_ROOMS = 15000
const MIN_ZONES = 60
const MIN_REGISTERED_KINDS = 4

let pass = 0
let fail = 0
const skipped = []
const ok = (what, cond, detail = '') => {
  if (cond) {
    pass += 1
    console.log(`OK   ${what.padEnd(72)} ${detail}`)
  } else {
    fail += 1
    console.log(`FAIL ${what.padEnd(72)} ${detail}`)
  }
}

/**
 * The third state, and the reason this file has one at all.
 *
 * Rule 3 below - every primitive the content asks for has a factory registered
 * in Godot - is answered by a `.gd` file this repository does not currently
 * hold. Folding that into a pass would report a contract that was never
 * checked; folding it into a failure would report a defect nobody introduced.
 * `tools/run-tests.mjs` collects every line carrying this marker and refuses to
 * print "all passed" over one.
 */
const notChecked = (what, why) => {
  skipped.push(`${what}: ${why}`)
  console.log(`NOT CHECKED ${what.padEnd(65)} ${why}`)
}

// ------------------------------------------------------- 1. no drift

let checkOutput = ''
let checkFailed = false
try {
  checkOutput = execFileSync(
    process.execPath,
    ['--experimental-strip-types', 'tools/build-world-content.mjs', '--check'],
    { encoding: 'utf8' }
  )
} catch (error) {
  checkFailed = true
  checkOutput = `${error.stdout ?? ''}${error.stderr ?? ''}`
}
const checkedFiles = Number(/OK\s+(\d+) generated files match/.exec(checkOutput)?.[1] ?? 0)
ok(
  'the committed content is byte-for-byte what the builder produces',
  !checkFailed && checkedFiles >= MIN_ZONES,
  checkFailed
    ? `builder --check exited non-zero: ${checkOutput.split('\n').find((line) => line.startsWith('FAIL')) ?? 'no FAIL line'}`
    : `${checkedFiles} files compared, floor ${MIN_ZONES}`
)

// ------------------------------------------------------ 2. coverage

const mapZones = readdirSync(MAP_DIR)
  .filter((name) => name.endsWith('.json') && name !== 'index.json')
  .map((name) => JSON.parse(readFileSync(join(MAP_DIR, name), 'utf8')))
const index = JSON.parse(readFileSync(join(WORLD_DIR, 'index.json'), 'utf8'))

let mapRooms = 0
let matched = 0
let missingZones = 0
const missingExamples = []
for (const zone of mapZones) {
  let content = null
  try {
    content = JSON.parse(readFileSync(join(WORLD_DIR, `${zone.id}.json`), 'utf8'))
  } catch {
    missingZones += 1
    continue
  }
  const byId = new Map(content.rooms.map((room) => [room.id, room]))
  for (const room of zone.rooms ?? []) {
    mapRooms += 1
    if (byId.has(room.id)) matched += 1
    else if (missingExamples.length < 5) missingExamples.push(`${zone.id}-${room.id}`)
  }
}

ok(
  'the map itself is all there, so the counts below mean something',
  mapRooms >= MIN_ROOMS && mapZones.length >= MIN_ZONES,
  `${mapRooms} rooms in ${mapZones.length} zones, floors ${MIN_ROOMS}/${MIN_ZONES}`
)
ok(
  'every room in every zone has a content entry',
  matched === mapRooms && missingZones === 0,
  `${matched} of ${mapRooms}${missingZones ? `, ${missingZones} zones have no content file` : ''}${missingExamples.length ? `, e.g. ${missingExamples.join(' ')}` : ''}`
)
ok(
  "and the index agrees with what the zone files hold, so it cannot flatter",
  index.counts.rooms === mapRooms && index.counts.zones === mapZones.length,
  `index says ${index.counts.rooms} rooms in ${index.counts.zones} zones`
)

// ------------------------------------- 3. only kinds the viewer can draw

/**
 * The registered set, read out of whichever `.gd` registers content factories
 * rather than typed here.
 *
 * `ContentRegistry.register("<kind>", …)` is the one call that makes a kind
 * drawable, so every such line is a kind the viewer can actually draw. A
 * hand-written copy of that list would agree with GDScript by coincidence,
 * which is the class of defect this rule exists for.
 *
 * It is found by that call rather than by filename. Until 9 Sep 2026 the path
 * `godot/scripts/shared_asset_content.gd` was hardcoded here, and when the 3D
 * subsystem was deleted (docs/NO-3D.md) this file died on ENOENT before
 * reaching any of the rules below it - a whole suite lost to one absent
 * optional input. Scanning for the call means the rule re-arms by itself when
 * the 2D pack lands under whatever name its owner gives it.
 */
const pack = findContentPack()
if (pack) {
  ok(
    'the Godot content pack still declares a registry of kinds this can read',
    pack.registered.length >= MIN_REGISTERED_KINDS,
    `${pack.registered.length} kinds registered in ${pack.file}: ${[...pack.registered].sort().join(', ')} (floor ${MIN_REGISTERED_KINDS})`
  )
} else {
  notChecked('the Godot content pack still declares a registry of kinds this can read', NO_CONTENT_PACK_REASON)
}
const registered = new Set(pack?.registered ?? [])

let primitivesAsked = 0
const undrawable = new Map()
const groundSeen = new Set()
const ruleSeen = new Set()
let blockAgrees = 0
let contentRooms = 0
for (const zone of mapZones) {
  const content = JSON.parse(readFileSync(join(WORLD_DIR, `${zone.id}.json`), 'utf8'))
  for (const room of content.rooms) {
    contentRooms += 1
    groundSeen.add(room.ground)
    ruleSeen.add(room.rule)
    if (blockKindFor(room.ground) === room.block) blockAgrees += 1
    for (const primitive of primitivesFor({
      blockKind: room.block,
      tags: room.classification.tags,
      boundaryEdges: room.boundaryEdges,
    })) {
      primitivesAsked += 1
      if (pack && !registered.has(primitive.kind)) {
        undrawable.set(primitive.kind, (undrawable.get(primitive.kind) ?? 0) + 1)
      }
    }
  }
}

// The denominator, kept whether or not there is a pack to compare against. It
// is the number that goes to zero when the content or `primitivesFor()` stops
// producing anything, and without it the rule below would be "no kind is
// undrawable" over nothing - which is what a run against an empty
// `src/data/world` says too. Asserted separately so the pack's absence costs
// this suite one rule and not two.
ok(
  'the content still asks for primitives, so the drawability rule has something to judge',
  primitivesAsked >= MIN_ROOMS,
  `${primitivesAsked} primitives asked for across ${contentRooms} rooms, floor ${MIN_ROOMS}`
)

if (pack) {
  ok(
    'every primitive the content asks for has a factory registered in Godot',
    undrawable.size === 0,
    undrawable.size
      ? `${primitivesAsked} asked for; unregistered: ${[...undrawable].map(([kind, n]) => `${kind} x${n}`).join(', ')}`
      : `${primitivesAsked} primitives asked for across ${contentRooms} rooms, all registered against ${pack.file}`
  )
} else {
  notChecked('every primitive the content asks for has a factory registered in Godot', NO_CONTENT_PACK_REASON)
}

// -------------------------------------------------- 4. the unknown ceiling

// Read out of the published index, not imported from the builder: the builder
// is a script, so importing it would run the whole batch, and the number that
// has to hold is the one the artefact was actually built under. It travels with
// the artefact for that reason.
const ceiling = index.unknownCeilingPercent
ok(
  'the content publishes the ceiling it was built under',
  typeof ceiling === 'number' && ceiling > 0 && ceiling <= 5,
  `unknownCeilingPercent: ${ceiling}`
)
ok(
  'the unknown share is under the ceiling',
  index.counts.unknownPercent < ceiling && index.counts.unknown > 0,
  `${index.counts.unknown} of ${index.counts.rooms} = ${index.counts.unknownPercent}%, ceiling ${ceiling}% (a zero here would mean the residue list stopped being written)`
)

// ------------------------------------------------ 5. total vocabularies

ok(
  'every ground kind a record carries is one of the declared kinds',
  [...groundSeen].every((kind) => GROUND_KINDS.includes(kind)) && groundSeen.size > 5,
  `${groundSeen.size} distinct: ${[...groundSeen].sort().join(', ')}`
)
ok(
  'every rule a record names is one of the declared rules',
  [...ruleSeen].every((rule) => GROUND_RULES.includes(rule)) && ruleSeen.size > 2,
  `${ruleSeen.size} distinct: ${[...ruleSeen].sort().join(', ')}`
)
ok(
  "every room's block kind is the one its ground kind maps to",
  blockAgrees === contentRooms && contentRooms >= MIN_ROOMS,
  `${blockAgrees} of ${contentRooms}`
)
ok(
  'the ground-to-block map is total over the ground vocabulary',
  GROUND_KINDS.every((kind) => BLOCK_KINDS.includes(blockKindFor(kind))),
  `${GROUND_KINDS.length} ground kinds -> ${BLOCK_KINDS.length} block kinds`
)

// ------------------------------------------------- 6. place cohorts
//
// Fixtures rather than the shipped map, because these properties are about what
// the rule does with an input and the shipped map cannot be asked for a 1:1
// split on demand. Every fixture is named in its check, so a sabotage says which
// one it broke rather than only that something went red.
//
// Section 7 then re-derives the cohorts from `src/data/map` and the committed
// content: the fixtures prove the rule, that proves the artefact was built by
// it.

const cohortRoom = (id, place, exits = []) => ({ id, place, exits })
const answers = (table) => (id) => table[id]

// A `go` exit is a doorway, not a walk edge, and a threshold is exactly where
// the ground changes. Sabotage: count `go` as a walk edge and this says 1.
const doorFixture = [
  cohortRoom(1, 'Tunnel', [{ dir: 'go', to: 2 }]),
  cohortRoom(2, 'Tunnel', [{ dir: 'go', to: 1 }]),
]
const doorCohorts = placeCohorts(doorFixture)
ok(
  'fixture door: two same-place rooms joined only by a go exit are two cohorts',
  doorCohorts.length === 2 && doorCohorts.every((cohort) => cohort.ids.length === 1),
  `${doorCohorts.length} cohorts, sizes ${doorCohorts.map((c) => c.ids.length).join('/')} (thresholds: ${[...THRESHOLD_DIRECTIONS].join(' ')})`
)

// The same pair joined by a compass move is one cohort, so the check above is
// measuring the threshold rather than an empty graph.
const walkFixture = [
  cohortRoom(1, 'Tunnel', [{ dir: 'north', to: 2 }]),
  cohortRoom(2, 'Tunnel', [{ dir: 'south', to: 1 }]),
]
const walkCohorts = placeCohorts(walkFixture)
ok(
  'fixture walk: the same pair joined by a compass move is one cohort',
  walkCohorts.length === 1 && walkCohorts[0].ids.length === 2,
  `${walkCohorts.length} cohorts, sizes ${walkCohorts.map((c) => c.ids.length).join('/')}`
)

// A place name is not a place: a room of another name between two namesakes
// does not join them, which is what stops ten zones' worth of "Tunnel" voting
// together.
const namesakeFixture = [
  cohortRoom(1, 'Tunnel', [{ dir: 'north', to: 2 }]),
  cohortRoom(2, 'Bar', [
    { dir: 'north', to: 3 },
    { dir: 'south', to: 1 },
  ]),
  cohortRoom(3, 'Tunnel', [{ dir: 'south', to: 2 }]),
]
const namesakeCohorts = placeCohorts(namesakeFixture)
ok(
  'fixture namesake: one place name either side of another place is two cohorts',
  namesakeCohorts.length === 3 && namesakeCohorts.every((cohort) => cohort.ids.length === 1),
  `${namesakeCohorts.length} cohorts, sizes ${namesakeCohorts.map((c) => c.ids.length).join('/')}`
)

const twoThirds = unifyPlaceCohort(
  [1, 2, 3],
  answers({
    1: { kind: 'street', rule: 'neighbour' },
    2: { kind: 'street', rule: 'neighbour' },
    3: { kind: 'grass', rule: 'neighbour' },
  })
)
ok(
  'fixture two-thirds: 2 of 3 on the same rule unifies the third',
  twoThirds.state === 'unified' && twoThirds.kind === 'street' && twoThirds.changed.length === 1,
  `${twoThirds.state} to ${twoThirds.kind}, ${twoThirds.changed.length} room(s) moved`
)

// "Via Iltesh": two rooms, one street and one grass, both decided by
// propagation, and nothing in the data prefers either.
const evenSplit = unifyPlaceCohort(
  [1, 2],
  answers({ 1: { kind: 'street', rule: 'neighbour' }, 2: { kind: 'grass', rule: 'neighbour' } })
)
ok(
  'fixture even-split: a 1 of 2 tie is held, not unified',
  evenSplit.state === 'held' && evenSplit.reasonKey === 'tie' && evenSplit.changed.length === 0,
  `${evenSplit.state}: ${evenSplit.reason ?? ''}`
)

// Between a tie and two thirds is a band that is a majority and is not enough.
// This is the fixture a lowered gate breaks: 3 of 5 passes a bare majority.
const shortMajority = unifyPlaceCohort(
  [1, 2, 3, 4, 5],
  answers({
    1: { kind: 'street', rule: 'neighbour' },
    2: { kind: 'street', rule: 'neighbour' },
    3: { kind: 'street', rule: 'neighbour' },
    4: { kind: 'grass', rule: 'neighbour' },
    5: { kind: 'grass', rule: 'neighbour' },
  })
)
ok(
  'fixture short-majority: 3 of 5 is a majority, is under two thirds, and is held',
  shortMajority.state === 'held' &&
    shortMajority.reasonKey === 'below two thirds' &&
    COHORT_MAJORITY_NUMERATOR * 5 > COHORT_MAJORITY_DENOMINATOR * 3,
  `${shortMajority.state}: ${shortMajority.reason ?? ''} (gate ${COHORT_MAJORITY_NUMERATOR}/${COHORT_MAJORITY_DENOMINATOR})`
)

// A minority decided by a stronger rule outranks the cohort: a room whose own
// title says water is not overruled by neighbour-decided streets.
const strongerMinority = unifyPlaceCohort(
  [1, 2, 3],
  answers({
    1: { kind: 'street', rule: 'neighbour' },
    2: { kind: 'street', rule: 'neighbour' },
    3: { kind: 'water', rule: 'title' },
  })
)
ok(
  'fixture stronger-minority: a title-decided room survives a neighbour-decided majority',
  strongerMinority.state === 'held' &&
    strongerMinority.reasonKey === 'a minority room outranks the majority' &&
    ruleStrength('title') < ruleStrength('neighbour'),
  `${strongerMinority.state}: ${strongerMinority.reason ?? ''}`
)

// The same shape the other way round does unify, so the check above is measuring
// the ladder rather than refusing every three-room cohort.
const weakerMinority = unifyPlaceCohort(
  [1, 2, 3],
  answers({
    1: { kind: 'street', rule: 'title' },
    2: { kind: 'street', rule: 'title' },
    3: { kind: 'water', rule: 'neighbour' },
  })
)
ok(
  'fixture weaker-minority: a neighbour-decided room does not survive a title-decided majority',
  weakerMinority.state === 'unified' && weakerMinority.changed.length === 1,
  `${weakerMinority.state} to ${weakerMinority.kind}`
)

const unknownMajority = unifyPlaceCohort(
  [1, 2, 3],
  answers({
    1: { kind: 'unknown', rule: 'unknown' },
    2: { kind: 'unknown', rule: 'unknown' },
    3: { kind: 'street', rule: 'neighbour' },
  })
)
ok(
  'fixture unknown-majority: a mostly-unknown cohort is held, never unified to unknown',
  unknownMajority.state === 'held' && unknownMajority.reasonKey === 'majority unknown',
  `${unknownMajority.state}: ${unknownMajority.reason ?? ''}`
)

// ------------------------------- 7. the committed content agrees with the rule

const cohortIndex = index.cohorts ?? null
let cohortRuled = 0
let cohortUnknown = 0
for (const zone of mapZones) {
  const content = JSON.parse(readFileSync(join(WORLD_DIR, `${zone.id}.json`), 'utf8'))
  for (const room of content.rooms) {
    if (room.rule !== 'cohort') continue
    cohortRuled += 1
    if (room.ground === 'unknown') cohortUnknown += 1
  }
}
ok(
  'the content publishes what the cohort pass did, and the rooms bear it out',
  cohortIndex != null && cohortIndex.changedRooms > 0 && cohortRuled === cohortIndex.changedRooms,
  cohortIndex
    ? `index says ${cohortIndex.changedRooms} rooms moved, ${cohortRuled} carry rule "cohort"; ${cohortIndex.unified} cohorts unified, ${cohortIndex.held} held ${JSON.stringify(cohortIndex.heldBy)}`
    : 'index.cohorts is absent'
)
ok(
  'the cohort pass never publishes an unknown, so it cannot raise the unknown share',
  cohortUnknown === 0 && cohortRuled > 0,
  `${cohortUnknown} of ${cohortRuled} cohort-decided rooms are unknown`
)
ok(
  'and it left fewer same-place name groups disagreeing than it found',
  cohortIndex != null && cohortIndex.nameGroupsSplitAfter < cohortIndex.nameGroupsSplitBefore,
  cohortIndex
    ? `${cohortIndex.nameGroupsSplitBefore} split before the pass, ${cohortIndex.nameGroupsSplitAfter} after`
    : 'index.cohorts is absent'
)

// Re-derive the cohorts from the map and the committed content and hold the
// artefact to the numbers the index claims. A hand-edited ground kind shows up
// here as a cohort that disagrees and was never held.
let derivedDisagreeing = 0
let derivedCohorts = 0
for (const zone of mapZones) {
  const content = JSON.parse(readFileSync(join(WORLD_DIR, `${zone.id}.json`), 'utf8'))
  const groundOf = new Map(content.rooms.map((room) => [room.id, room.ground]))
  for (const cohort of placeCohorts(zone.rooms ?? [])) {
    derivedCohorts += 1
    if (cohort.ids.length < 2) continue
    if (new Set(cohort.ids.map((id) => groundOf.get(id))).size > 1) derivedDisagreeing += 1
  }
}
ok(
  'every cohort left disagreeing in the committed content is one the pass held on purpose',
  cohortIndex != null &&
    derivedCohorts === cohortIndex.total &&
    derivedDisagreeing === cohortIndex.held &&
    derivedCohorts > 1000,
  cohortIndex
    ? `${derivedCohorts} cohorts re-derived (index ${cohortIndex.total}), ${derivedDisagreeing} still disagree (index held ${cohortIndex.held})`
    : 'index.cohorts is absent'
)

console.log(`\n${pass + fail} checked, ${fail} failed`)
if (fail) process.exit(1)
if (skipped.length) {
  // Deliberately does not repeat the marker token: `run-tests.mjs` collects
  // every line carrying it, and a summary echoing it would report one skip as
  // two and inflate the count it exists to make honest.
  console.log(`no failures, but ${skipped.length} rule(s) went unchecked: ${skipped.join('; ')}`)
  process.exit(0)
}
console.log('all passed')
